let colors=['#3e3e4b','#8c1c00','#ed5f00','#faf8a5','#681f01']
let drips=[]
let fall=0
let theFont

function preload(){
theFont=loadFont('https://openprocessing.org/sketch/1956501/files/EBGaramond-VariableFont_wght.ttf')
}

function setup() {
	createCanvas(windowHeight, windowHeight);
	background('#E0DBD7');
	background(255)
  pixelDensity(1)

	loadPixels()
	for(let x=0; x<width; x++){
		for(let y=0; y<height; y+=floor(random(1, 4))){
	var index = (x + y * width)*4;
		let avalue= map(noise(x/100, y/100), 0, 1, 0, 255)
	  pixels[index+0]= 0;
    pixels[index+1]= 0;
    pixels[index+2]= 0;
    pixels[index+3]= avalue;		
		}
	}
updatePixels()
	let space= width/20
	textSize(width/30)
	textFont(theFont)
	push()
	translate(width/8, height/3)
	noStroke()
	fill(50)


	pop()


}

function draw() {

	if(fall<height){
		if(frameRate<40){
	fall+=1
	} else{
	fall+=0.2	
	}
	}
	if(frameCount%2==0){
	let x= random(width)
	let y= random(-20, fall)


	let c=colors[floor(map(y, -20, height, 0, 5))]


	let xr=random(0, 100)
	let yr=random(0, 100)
	let xVel=random(-0.2, 0.2)
	let yVel= random(random(3.2, 5))
	let v= createVector(xVel, yVel)
	let amount= floor(random(1, 22))
	for(let i=0; i<amount; i++){
	drips.push(new drip(x+randomGaussian(0, xr), y+randomGaussian(0, yr), color(c), v))
	}
	}
	for(let d of drips){
		d.droop();
		d.dry();
	}

//uncomment the following lines if you want things to start getting weird

	// let g=get()
	// push()
	// clear()
	// image(g, -width*0.0001, -height*0.0001, width*1.0002, height*1.0001)
	// pop()

}



class drip {
	constructor(x, y, c, v){
		this.pos= createVector(x, y);
		this.acc= createVector(0, 0);
		this.vel= v
		this.color=c;
		this.stroke=c
		this.alpha=50

		this.size=random(3, 10)
		if(frameCount<100){
		this.sizeVel=random(0.45, 5)	
		} else{
		this.sizeVel=random(0.3, 0.5)
		}
		this.sizeD= this.size*2
		this.sizeAcc=-this.sizeVel/100
		this.sNoise=random(1000)
		this.timer=0
		this.r= this.vel.heading()
	}

	 droop(){
		 this.sNoise+=0.01
		 this.timer+=1
		 if(this.vel.y>0.1){
			this.acc=createVector(0, -0.01)
		 } else{
			 this.acc=createVector(0, 0)
			 this.vel=createVector(0, 0)
		 }

	this.vel.add(this.acc);
	this.pos.add(this.vel);
		this.alpha-=0.1
	this.stroke.setAlpha(this.alpha/2)
	this.color.setAlpha(this.alpha)
	fill(this.color)
	stroke(this.stroke)
if(this.size<this.sizeD){
	this.size+=this.sizeVel
}
	let sOff= map(noise(frameCount/100, this.sNoise), 0, 1, -this.size/3, this.size/3)
	push()
		 translate(this.pos.x, this.pos.y)
		 rotate(this.r-PI/2)
	arc(0, 0, this.size+sOff, this.size+sOff, 0, PI)
		pop()
	 }	 

	dry(){
		if(this.timer>100){
			 let index = drips.indexOf(this);
      drips.splice(index, 1);

		}

	}
}

